import { Assets, type Spritesheet, type Texture } from "pixi.js";

/**
 * Loads every spritesheet and image up front. Sheets are generated by tools/build_spritesheets.py.
 * Use `anim("player", "Run")` to get the frames for an animation, `image("hills")` for a single image.
 */
const SHEETS = {
  player: "assets/sprites/player.json",
  fx: "assets/sprites/fx_projectiles.json",
  super: "assets/sprites/fx_super.json",
} as const;

const IMAGES = {
  hills: "assets/backgrounds/hills.png",
} as const;

export type SheetName = keyof typeof SHEETS;
export type ImageName = keyof typeof IMAGES;

const sheets = {} as Record<SheetName, Spritesheet>;
const images = {} as Record<ImageName, Texture>;

export async function loadAssets(): Promise<void> {
  const sheetNames = Object.keys(SHEETS) as SheetName[];
  const imageNames = Object.keys(IMAGES) as ImageName[];
  const [loadedSheets, loadedImages] = await Promise.all([
    Promise.all(sheetNames.map((n) => Assets.load<Spritesheet>(SHEETS[n]))),
    Promise.all(imageNames.map((n) => Assets.load<Texture>(IMAGES[n]))),
  ]);
  sheetNames.forEach((n, i) => (sheets[n] = loadedSheets[i]));
  imageNames.forEach((n, i) => (images[n] = loadedImages[i]));
}

/** Frames of one animation. Throws a clear error on typos instead of rendering nothing. */
export function anim(sheet: SheetName, name: string): Texture[] {
  const frames = sheets[sheet]?.animations[name];
  if (!frames) throw new Error(`Animation "${name}" not found in sheet "${sheet}"`);
  return frames;
}

export function image(name: ImageName): Texture {
  return images[name];
}
